async function createRun(label,source){const {createBrowserGame:createGameServer}=await import(pathToFileURL(path.resolve(source,'scripts/browser-game-server.mjs'))),game=await createGameServer({dataDir:fs.mkdtempSync(path.join(os.tmpdir(),'kc5-qa-'+label+'-'))});game.room.paused=true;await new Promise(r=>game.server.listen(0,'127.0.0.1',r));const base=`http://127.0.0.1:${game.server.address().port}`,actors=[];out.services.push({label,base});return {label,game,base,actors,s:game.room.sim,r:game.room};}
