  if(label==='before'){await stop(run);continue;}
  for(const a of run.actors)for(let i=0;i<4;i++)await check(`current/class${a.id}/skill${i+1}/real-button-manual-result-SSE`,async()=>{const h=clean(run,a);h.hp=1e6;const enemyActor=run.actors.find(b=>b.p.side!==a.p.side),e=s.hero(enemyActor.p);Object.assign(e,{x:0,y:a.p.side?-3:3});const friends=Array.from({length:5},(_,j)=>troop(run,a.p.side,(j-2)*2.5,1));for(const u of friends)u.hp=1000;e.targetId=friends[0].id;h.targetId=e.id;for(let j=0;j<4;j++)troop(run,1-a.p.side,(j-1.5)*.3,a.p.side?-2:2);if(a.id===4){h.heat=5;h.heatUntil=s.time+15;}if(a.id===5&&i===2)for(const f of friends)s.debuff(f,e,'moveSlow',.3,10,null,true);await sync(run);const allySkill=a.id===0&&[1,2].includes(i)||a.id===5&&[1,2,3].includes(i),selected=allySkill?friends[0]:e;await clickUnit(a,selected.id);await a.page.waitForFunction(id=>__game.sim.hero().manualTargetId===id,selected.id);await a.page.waitForFunction(i=>__game.sim.castPlan(i).ok,i);await a.page.locator(`[data-cast="${i}"]`).click();await a.page.waitForFunction(i=>__game.sim.player.cd[i]>__game.sim.time,i);const cost=i===3?3:1;near(a.p.stamina,100-cost);advance(s,.4);await sync(run);await a.page.locator('#locate').click();await a.page.waitForTimeout(200);await shot(a.page,`current-class${a.id}-skill${i+1}`);advance(s,a.id===2&&i===2?3.1:a.id===3&&i===1?1.4:1);await sync(run);const all=await Promise.all(run.actors.map(b=>b.page.evaluate(()=>({sequence:__game.sim.sequence,units:__game.sim.units.map(u=>({id:u.id,hp:u.hp,shield:u.shield||0,manual:u.manualTargetId??null,cd:u.cd,stun:u.stunUntil||0})),damageEvents:__game.sim.animations.filter(e=>e.kind==='damage').map(e=>({id:e.id,amount:e.amount,targetId:e.targetId}))}))));for(const v of all)assert.equal(JSON.stringify(v.units),JSON.stringify(all[0].units));const value=s.skillValues.at(-1);assert.ok(value.spent<=value.limit+1e-7);const result={classId:a.id,skill:i+1,selectedId:selected.id,cost,value:structuredClone(value),hp:e.hp,selfHp:h.hp,fields:s.fields.map(f=>({kind:f.kind,type:f.type,host:f.host})),sequence:all[0].sequence,clients:all.length};out.skills.push(result);return result;});
  for(const id of[0,5])await check(`current/class${id}/friend-preserves-20-range-enemy-real-click`,async()=>{const a=run.actors.find(a=>a.id===id),h=clean(run,a);Object.assign(h,{x:0,y:0,speed:2,cd:0});const e=troop(run,1,0,-15),f=troop(run,0,2,0);await sync(run);await clickUnit(a,e.id);await a.page.waitForFunction(id=>__game.sim.hero().manualTargetId===id,e.id);await clickUnit(a,f.id);await a.page.waitForFunction(id=>__game.sim.hero().manualTargetId===id,f.id);const before={manual:h.manualTargetId,target:h.targetId,y:h.y};advance(s,.05);await sync(run);await a.page.locator('#locate').click();await a.page.waitForTimeout(300);await shot(a.page,`friend-loses-enemy-class${id}`);const views=await Promise.all(run.actors.map(a=>a.page.evaluate(id=>{const h=__game.sim.get(id);return{target:h.targetId,manual:h.manualTargetId,x:h.x,y:h.y};},h.id)));const evidence={classId:id,enemyId:e.id,friendId:f.id,before,after:{manual:h.manualTargetId,target:h.targetId,y:h.y},views};out.friend.push(evidence);assert.equal(h.targetId,e.id,JSON.stringify(evidence));return evidence;});
